-- Assumes orders(id, status, version) and outbox defined below.
BEGIN;
WITH changed AS (
  UPDATE orders SET status = 'PAID', version = version + 1
  WHERE id = 4711 RETURNING id, status, version
)
INSERT INTO outbox (id, aggregatetype, aggregateid, type, payload)
SELECT gen_random_uuid(), 'order', id::text, 'OrderPaid',
       jsonb_build_object('orderId', id, 'status', status, 'version', version)
FROM changed;
-- Cleanup is in the same transaction, after the INSERT statement.
DELETE FROM outbox WHERE aggregateid = '4711' AND type = 'OrderPaid';
COMMIT;

-- In database orders, as the table/publication owner:
CREATE TABLE orders (id bigint PRIMARY KEY, status text NOT NULL, version bigint NOT NULL);
CREATE TABLE outbox (
  id uuid PRIMARY KEY, aggregatetype text NOT NULL,
  aggregateid text NOT NULL, type text NOT NULL, payload jsonb NOT NULL
);
CREATE TABLE debezium_heartbeat (id integer PRIMARY KEY, ts timestamptz NOT NULL);
CREATE ROLE cdc LOGIN REPLICATION;
GRANT CONNECT ON DATABASE orders TO cdc;
GRANT USAGE ON SCHEMA public TO cdc;
GRANT SELECT ON outbox, debezium_heartbeat TO cdc;
GRANT INSERT, UPDATE ON debezium_heartbeat TO cdc;
CREATE PUBLICATION orders_outbox_pub FOR TABLE outbox, debezium_heartbeat;
